fn count_true(a: &[bool]) -> usize {
    // The prefix count function prefix_count(n) is defined as
    // the number of true values in the slice a[0..n].
    // Our goal is to return prefix_count(a.len()), i.e., the
    // count of true values in the entire array.

    // Initialize count to zero.
    let mut count = 0;

    // Iterate over each element and increment count if it is true.
    for &value in a {
        if value {
            count += 1;
        }
    }

    // By construction, count equals prefix_count(a.len()).
    // It respects the properties:
    // - 0 <= count <= a.len()
    // - prefix_count is monotonic since adding more elements
    //   cannot reduce the count of true values.
    count
}